originals: dict[str, bytes | None] = {}


def run(command: list[str]) -> None:
    print("$ " + " ".join(command))
    subprocess.run(command, cwd=ROOT, check=True)


def ensure_targets_are_safe() -> None:
    changed: list[str] = []

    for relative in FILES:
        path = ROOT / relative
        worktree = subprocess.run(
            ["git", "diff", "--quiet", "--", relative],
            cwd=ROOT,
        )
        staged = subprocess.run(
            ["git", "diff", "--cached", "--quiet", "--", relative],
            cwd=ROOT,
        )

        if worktree.returncode != 0 or staged.returncode != 0:
            changed.append(relative)
            continue

        tracked = subprocess.run(
            ["git", "ls-files", "--error-unmatch", relative],
            cwd=ROOT,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        ).returncode == 0

        if path.exists() and not tracked:
            changed.append(relative)

    if changed:
        raise RuntimeError(
            "These target files contain uncommitted or untracked "
            "content and were not overwritten:\n"
            + "\n".join(changed)
        )


def install_files() -> None:
    for relative, content in FILES.items():
        path = ROOT / relative
        originals[relative] = (
            path.read_bytes()
            if path.exists()
            else None
        )

        if path.exists():
            backup_path = BACKUP / relative
            backup_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, backup_path)

        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            textwrap.dedent(content).strip() + "\n",
            encoding="utf-8",
        )
        print(f"Installed: {relative}")


def restore() -> None:
    print("Restoring previous target files...")

    for relative, original in originals.items():
        path = ROOT / relative

        if original is None:
            if path.exists():
                path.unlink()
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(original)


def commit_and_push() -> None:
    paths = list(FILES)

    try:
        paths.append(
            str(Path(__file__).resolve().relative_to(ROOT))
        )
    except ValueError:
        pass

    run(["git", "add", "--", *paths])

    staged = subprocess.run(
        ["git", "diff", "--cached", "--quiet"],
        cwd=ROOT,
    )

    if staged.returncode == 0:
        print("Persistent paper operations are already committed.")
        return

    run([
        "git",
        "commit",
        "-m",
        "Implement QPX Bot persistent paper trading operations",
    ])

    branch = subprocess.check_output(
        ["git", "branch", "--show-current"],
        cwd=ROOT,
        text=True,
    ).strip()

    if not branch:
        raise RuntimeError("Cannot push from detached Git state.")

    run(["git", "push", "origin", branch])


def main() -> int:
    print("=" * 76)
    print("QPX BOT — PERSISTENT PAPER TRADING INSTALLER")
    print("=" * 76)
    print(f"Project: {ROOT}")

    ensure_targets_are_safe()
    install_files()

    try:
        run([sys.executable, "tests/run_all_tests.py"])
    except Exception:
        restore()
        raise

    commit_and_push()

    print()
    print("Initializing the simulated persistent paper account...")
    print()

    try:
        run([
            sys.executable,
            "QPX_RUN_PAPER.py",
            "--symbol",
            "SPY",
        ])
    except Exception:
        print()
        print("=" * 76)
        print("QPX PAPER OPERATIONS CODE: INSTALLED AND PUSHED")
        print("INITIAL DATA/PAPER RUN: NEEDS RETRY")
        print("=" * 76)
        print(
            "Re-run:\n"
            "python QPX_RUN_PAPER.py --symbol SPY"
        )
        return 2

    print()
    print("=" * 76)
    print("QPX PERSISTENT PAPER TRADING OPERATIONS: COMPLETE")
    print("=" * 76)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
